+    // aws ec2 describe-regions --all-regions --query "Regions[].{Name:RegionName}" --output text
+    std::set<const std::string> regions = {
+        "af-south-1",
+        "ap-east-1",
+        "ap-northeast-1",
+        "ap-northeast-2",
+        "ap-northeast-3",
+        "ap-south-1",
+        "ap-southeast-1",
+        "ap-southeast-2",
+        "ap-southeast-3",
+        "ca-central-1",
+        "eu-central-1",
+        "eu-north-1",
+        "eu-south-1",
+        "eu-west-1",
+        "eu-west-2",
+        "eu-west-3",
+        "me-central-1",
+        "me-south-1",
+        "sa-east-1",
+        "us-east-1",
+        "us-east-2",
+        "us-west-1",
+        "us-west-2",
+    };
+
+    const char *default_region = g_getenv("AWS_REGION");
+    if (default_region != NULL) {
+        regions.insert(default_region);
+    } else {
+        default_region = "From profile";
+    }
+
+    printf(
+        "arg {number=%d}"
+        "{call=--cloudtrail-aws-region}"
+        "{display=%s}"
+        "{type=editselector}"
+        "{default=%s}"
+        "{tooltip=%s}"
+        "{group=Capture}"
+        "\n",
+        arg_num, display, default_region, description);
+    printf ("value {arg=%d}{value=}{display=%s}{default=true}\n", arg_num, default_region);
+
+    for (auto &region : regions) {
+        printf(
+            "value {arg=%d}"
+            "{value=%s}"
+            "{display=%s}"
+            "\n",
+            arg_num, region.c_str(), region.c_str());
+    }
+}
